import { SQL } from 'bun';
import { randomBytes } from 'node:crypto';
import { readdir, readFile, rm, mkdir, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { format, resolveConfig } from 'prettier';
import { openBootStores } from '@/lib/boot-stores';
import { setDiagnosticSink } from '@/lib/log';
import type { SqlClient } from '@/lib/auth/sql';

/**
 * Marker placed at the top of every generated schema-reference document.
 */
export const GENERATED_HEADER =
  '<!-- Generated by integration/db-schema-reference.ts - do not edit. Run: bun run db:docs -->';

/**
 * One column as returned by `information_schema.columns` joined to `pg_catalog`.
 */
export type ColumnRow = {
  table_name: string;
  column_name: string;
  ordinal_position: number;
  data_type: string;
  udt_name: string;
  character_maximum_length: number | null;
  numeric_precision: number | null;
  numeric_scale: number | null;
  is_nullable: 'YES' | 'NO';
  column_default: string | null;
  is_identity: 'YES' | 'NO';
  is_pg_enum: boolean;
};

/**
 * One table constraint (`PRIMARY KEY`, `FOREIGN KEY`, `UNIQUE`, or `CHECK`).
 * `type` uses the `pg_constraint.contype` letters.
 */
export type ConstraintRow = {
  table_name: string;
  name: string;
  type: 'p' | 'f' | 'u' | 'c';
  columns: string[];
  definition: string;
  ref_table: string | null;
  ref_columns: string[];
};

/**
 * One index from `pg_index` / `pg_get_indexdef`, including primary indexes.
 */
export type IndexRow = {
  table_name: string;
  name: string;
  columns: string[];
  is_unique: boolean;
  is_primary: boolean;
  where: string | null;
  definition: string;
};

/**
 * Documented shape of a single column. `defaultText` is already rendered.
 */
export type ColumnModel = {
  name: string;
  kind: string;
  dbType: string;
  nullable: boolean;
  defaultText: string;
  references: { table: string; column: string } | null;
};

/**
 * A foreign key reduced to one referencing column and one referenced column.
 */
export type ForeignKeyModel = {
  table: string;
  constraint: string;
  column: string;
  refTable: string;
  refColumn: string;
  nullable: boolean;
  unique: boolean;
  identifying: boolean;
};

/**
 * A non-primary index (or a unique index) shown in the schema reference.
 */
export type IndexModel = {
  name: string;
  columns: string[];
  unique: boolean;
  where: string | null;
  definition: string;
};

/**
 * One table in the generated reference: columns, indexes, and foreign keys.
 */
export type TableModel = {
  name: string;
  columns: ColumnModel[];
  indexes: IndexModel[];
  foreignKeys: ForeignKeyModel[];
};

/**
 * The whole public schema as consumed by the reference renderer.
 */
export type SchemaModel = {
  tables: TableModel[];
};

const ARRAY_UDT_NAMES: Record<string, string> = {
  int2: 'smallint',
  int4: 'integer',
  int8: 'bigint',
  bool: 'boolean',
  float4: 'real',
  float8: 'double precision',
};

/**
 * Maps a Postgres array `udt_name` to the element type name used in the reference.
 * Known internal names use `ARRAY_UDT_NAMES`; any other name drops a leading underscore.
 * @param udtName - `information_schema.columns.udt_name` of an `ARRAY` column.
 * @returns Element type name, e.g. `integer` for `_int4` or `text` for `_text`.
 */
function arrayElementName(udtName: string): string {
  const element = udtName.replace(/^_/, '');
  return ARRAY_UDT_NAMES[element] ?? element;
}

/**
 * True when `definition` is a CHECK that pins exactly `column` to a fixed
 * literal list (`= ANY (ARRAY[...])` or `IN (...)`), optionally combined with
 * `OR column IS NULL`. Any other column, predicate, or shape yields false.
 * Literal values are not returned.
 * @param definition - `pg_get_constraintdef` text of one CHECK constraint.
 * @param column - Column the CHECK must pin.
 * @returns Whether the CHECK is a fixed literal list on exactly that column.
 */
export function isEnumCheck(definition: string, column: string): boolean {
  const normalized = collapseSqlSpace(definition.trim());
  const interior = unwrapCheck(normalized);
  if (interior === null) return false;

  const parts = splitTopLevelOr(stripOuterParens(interior));
  if (parts.length < 1 || parts.length > 2) return false;

  let sawList = false;
  let sawNull = false;
  for (const part of parts) {
    const clause = stripOuterParens(part);
    if (matchesLiteralList(clause, column)) {
      if (sawList) return false;
      sawList = true;
    } else if (matchesIsNull(clause, column)) {
      if (sawNull) return false;
      sawNull = true;
    } else {
      return false;
    }
  }
  return sawList;
}

/**
 * Maps a PostgreSQL `data_type` / `udt_name` pair to the reference's base kind.
 * `USER-DEFINED` becomes `ENUM` only when `isPgEnum` is set.
 * @param dataType - `information_schema.columns.data_type`.
 * @param udtName - `information_schema.columns.udt_name` (array element type for `ARRAY`).
 * @param isPgEnum - Whether the column type is a Postgres enum type.
 * @returns Base kind such as `Integer`, `Free text` or `ENUM`.
 */
export function baseKind(dataType: string, udtName: string, isPgEnum: boolean): string {
  if (dataType === 'USER-DEFINED' && isPgEnum) return 'ENUM';
  if (dataType === 'integer' || dataType === 'bigint' || dataType === 'smallint') return 'Integer';
  if (dataType === 'numeric' || dataType === 'double precision' || dataType === 'real') {
    return 'Decimal';
  }
  if (dataType === 'boolean') return 'Boolean';
  if (
    dataType.startsWith('timestamp') ||
    dataType.startsWith('date') ||
    dataType.startsWith('time')
  ) {
    return 'Date/time';
  }
  if (dataType === 'text' || dataType === 'character varying' || dataType === 'character') {
    return 'Free text';
  }
  if (dataType === 'json' || dataType === 'jsonb') return 'JSON';
  if (dataType === 'uuid') return 'UUID';
  if (dataType === 'bytea') return 'Binary';
  if (dataType === 'ARRAY') return `Array of ${arrayElementName(udtName)}`;
  return dataType;
}

/**
 * Specializes a base kind for primary keys, identity columns, foreign keys, and enums.
 * An auto-increment primary key is always reported as an integer key.
 * @param input - Base kind and the key, enum and identity flags of one column.
 * @returns Kind cell text.
 */
export function columnKind(input: {
  base: string;
  isEnum: boolean;
  isPrimaryKey: boolean;
  isAutoIncrement: boolean;
  isForeignKey: boolean;
}): string {
  const kind = input.isEnum ? 'ENUM' : input.base;
  if (input.isPrimaryKey && input.isAutoIncrement) {
    return 'Integer (primary key, auto-increment)';
  }
  if (input.isPrimaryKey) return `${kind} (primary key)`;
  if (input.isForeignKey) return `${kind} (foreign key)`;
  return kind;
}

/**
 * Renders the SQL type shown in the reference, including character length,
 * numeric precision, array element types, and user-defined type names.
 * @param row - Catalog row of one column.
 * @returns Postgres type as shown in the reference, e.g. `character varying(32)` or `character(8)`.
 */
export function dbType(
  row: Pick<
    ColumnRow,
    'data_type' | 'udt_name' | 'character_maximum_length' | 'numeric_precision' | 'numeric_scale'
  >,
): string {
  if (row.data_type === 'character varying' && row.character_maximum_length !== null) {
    return `character varying(${row.character_maximum_length})`;
  }
  if (row.data_type === 'character' && row.character_maximum_length !== null) {
    return `character(${row.character_maximum_length})`;
  }
  if (row.data_type === 'numeric' && row.numeric_precision !== null) {
    return `numeric(${row.numeric_precision},${row.numeric_scale ?? 0})`;
  }
  if (row.data_type === 'ARRAY') return `${arrayElementName(row.udt_name)}[]`;
  if (row.data_type === 'USER-DEFINED') return row.udt_name;
  return row.data_type;
}

/**
 * Renders a column default for the reference.
 * Identity and `nextval(` become `auto-increment`; a missing default becomes an en dash.
 * String literals lose their quotes and cast; other literals and expressions stay SQL, in backticks.
 * @param columnDefault - `column_default` from the catalog, or `null`.
 * @param isIdentity - Whether the column is an identity column.
 * @returns Default cell text.
 */
export function renderDefault(columnDefault: string | null, isIdentity: boolean): string {
  if (isIdentity) return 'auto-increment';
  if (columnDefault === null) return '\u2013';

  const text = columnDefault.trim();
  if (text.startsWith('nextval(')) return 'auto-increment';

  const literal = /^'((?:''|[^'])*)'(?:::.+)?$/.exec(text);
  if (literal?.[1] !== undefined) {
    // An empty literal would render as an empty code span, which Markdown shows as two backticks.
    if (literal[1] === '') return "`''`";
    return `\`${literal[1].replace(/''/g, "'")}\``;
  }

  return `\`${text}\``;
}

/**
 * Crow's-foot cardinality of a foreign key from the referencing side.
 * Uniqueness means a primary-key or unique constraint with exactly the key's column set;
 * a wider unique that merely covers it does not count.
 * A unique foreign key is one-to-one: the child side is always optional-one `|o`, and the parent
 * side is `||` when the foreign-key column is NOT NULL or `o|` when it is nullable
 * (`|o--||` / `|o--o|`).
 * Many-to-one stays `}o--||` / `}o--o|`.
 * The line is solid (`--`) for an identifying relationship, whose columns are all part of the child's
 * primary key, and dashed (`..`) otherwise, as Mermaid defines them.
 * @param fkNullable - Whether the foreign-key column accepts NULL.
 * @param fkUnique - Whether the foreign-key column set is unique.
 * @param fkIdentifying - Whether every foreign-key column is part of the child's primary key.
 * @returns Mermaid relationship symbol.
 */
export function cardinality(
  fkNullable: boolean,
  fkUnique: boolean,
  fkIdentifying: boolean,
): `${'}o' | '|o'}${'--' | '..'}${'o|' | '||'}` {
  const child = fkUnique ? '|o' : '}o';
  const line = fkIdentifying ? '--' : '..';
  return `${child}${line}${fkNullable ? 'o|' : '||'}`;
}

/**
 * Compares a freshly rendered path-to-text map with the committed one.
 * `missing` exists only in `rendered`, `stale` only in `committed`, `differing` in both with different text.
 * Each list is sorted by path.
 * @param rendered - Freshly rendered path-to-text map.
 * @param committed - Path-to-text map read from the repository.
 * @returns Missing, differing and stale paths, each sorted.
 */
export function compareToCommitted(
  rendered: Map<string, string>,
  committed: Map<string, string>,
): { missing: string[]; differing: string[]; stale: string[] } {
  const missing: string[] = [];
  const differing: string[] = [];
  const stale: string[] = [];

  for (const [name, text] of rendered) {
    const previous = committed.get(name);
    if (previous === undefined) missing.push(name);
    else if (previous !== text) differing.push(name);
  }

  for (const name of committed.keys()) {
    if (!rendered.has(name)) stale.push(name);
  }

  missing.sort();
  differing.sort();
  stale.sort();
  return { missing, differing, stale };
}

function collapseSqlSpace(sql: string): string {
  let out = '';
  let inString = false;
  for (let i = 0; i < sql.length; i++) {
    const char = sql[i] ?? '';
    if (inString) {
      out += char;
      if (char === "'" && sql[i + 1] === "'") {
        out += "'";
        i += 1;
      } else if (char === "'") {
        inString = false;
      }
      continue;
    }
    if (char === "'") {
      inString = true;
      out += char;
      continue;
    }
    if (/\s/.test(char)) {
      if (!out.endsWith(' ')) out += ' ';
      continue;
    }
    out += char;
  }
  return out.trim();
}

function unwrapCheck(definition: string): string | null {
  const match = /^CHECK\s*\(/i.exec(definition);
  if (!match) return null;
  const open = match[0].length - 1;
  const span = sliceMatchingParen(definition, open);
  if (span === null || definition.slice(span.end).trim() !== '') return null;
  return span.content;
}

function sliceMatchingParen(sql: string, open: number): { content: string; end: number } | null {
  if (sql[open] !== '(') return null;
  let depth = 0;
  let inString = false;
  for (let i = open; i < sql.length; i++) {
    const char = sql[i] ?? '';
    if (inString) {
      if (char === "'" && sql[i + 1] === "'") {
        i += 1;
      } else if (char === "'") {
        inString = false;
      }
      continue;
    }
    if (char === "'") {
      inString = true;
      continue;
    }
    if (char === '(') depth += 1;
    else if (char === ')') {
      depth -= 1;
      if (depth === 0) {
        return { content: sql.slice(open + 1, i), end: i + 1 };
      }
    }
  }
  return null;
}

function stripOuterParens(sql: string): string {
  let current = sql.trim();
  while (current.startsWith('(') && current.endsWith(')')) {
    const span = sliceMatchingParen(current, 0);
    if (span === null || span.end !== current.length) break;
    current = span.content.trim();
  }
  return current;
}

function splitTopLevelOr(sql: string): string[] {
  const parts: string[] = [];
  let inString = false;
  let depth = 0;
  let start = 0;
  for (let i = 0; i < sql.length; i++) {
    const char = sql[i] ?? '';
    if (inString) {
      if (char === "'" && sql[i + 1] === "'") i += 1;
      else if (char === "'") inString = false;
      continue;
    }
    if (char === "'") {
      inString = true;
      continue;
    }
    if (char === '(') depth += 1;
    else if (char === ')') depth -= 1;
    else if (depth === 0 && /^or\b/i.test(sql.slice(i))) {
      const before = i === 0 ? '' : (sql[i - 1] ?? '');
      if (before === '' || /[\s(]/.test(before)) {
        parts.push(sql.slice(start, i));
        // Leave `i` on the second letter so the loop step lands on the next character.
        i += 1;
        start = i + 1;
      }
    }
  }
  parts.push(sql.slice(start));
  return parts;
}

function columnRef(column: string): string {
  const escaped = escapeRegExp(column);
  if (/^[A-Za-z_][A-Za-z0-9_]*$/.test(column)) return `(?:"${escaped}"|\\b${escaped}\\b)`;
  return `"${escaped}"`;
}

function matchesLiteralList(clause: string, column: string): boolean {
  const col = `(?:\\(\\s*${columnRef(column)}\\s*\\)|${columnRef(column)})(?:${castType()})?`;
  const literal = `'(?:''|[^'])*'(?:${castType()})?`;
  const list = `${literal}(?:\\s*,\\s*${literal})*`;
  const anyList =
    `${col}\\s*=\\s*ANY\\s*\\(\\s*\\(?\\s*ARRAY\\s*\\[\\s*${list}\\s*\\]\\s*\\)?` +
    `(?:${castType()})?\\s*\\)`;
  const inList = `${col}\\s+IN\\s*\\(\\s*${list}\\s*\\)`;
  // Postgres stores a one-value `IN ('x')` as `col = 'x'::text`.
  const single = `${col}\\s*=\\s*${literal}`;
  return new RegExp(`^(?:${anyList}|${inList}|${single})$`, 'i').test(clause);
}

function matchesIsNull(clause: string, column: string): boolean {
  const col = `(?:\\(\\s*${columnRef(column)}\\s*\\)|${columnRef(column)})(?:${castType()})?`;
  return new RegExp(`^${col}\\s+IS\\s+NULL$`, 'i').test(clause);
}

function castType(): string {
  const word = `[A-Za-z_][A-Za-z0-9_$]*`;
  const typeName = `(?:${word}\\s+){0,3}${word}`;
  return `(?:\\s*::\\s*(?:(?:"[^"]+"|${word})\\s*\\.\\s*)?(?:"[^"]+"|${typeName})(?:\\s*\\[\\s*\\])?)`;
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/**
 * Pure catalog rows turned into a sorted schema model.
 *
 * Tables are ordered by name. Columns follow `ordinal_position`. Indexes are ordered by
 * their column list and then by definition. Foreign keys are ordered by column.
 * @param columns - Column catalog rows.
 * @param constraints - Constraint catalog rows.
 * @param indexes - Index catalog rows.
 * @returns Sorted schema model.
 */
export function buildSchemaModel(
  columns: ColumnRow[],
  constraints: ConstraintRow[],
  indexes: IndexRow[],
): SchemaModel {
  const columnsByTable = new Map<string, ColumnRow[]>();
  for (const column of columns) {
    const list = columnsByTable.get(column.table_name);
    if (list) list.push(column);
    else columnsByTable.set(column.table_name, [column]);
  }

  const tables: TableModel[] = [...columnsByTable.keys()].sort(compareText).map((tableName) => {
    const tableColumns = [...(columnsByTable.get(tableName) ?? [])].sort(
      (left, right) => left.ordinal_position - right.ordinal_position,
    );
    const tableConstraints = constraints.filter((row) => row.table_name === tableName);
    const primaryColumns = new Set(
      tableConstraints.filter((row) => row.type === 'p').flatMap((row) => row.columns),
    );
    const foreignKeyConstraints = tableConstraints.filter((row) => row.type === 'f');
    const checkConstraints = tableConstraints.filter((row) => row.type === 'c');
    const foreignKeyColumns = new Set(foreignKeyConstraints.flatMap((row) => row.columns));

    const columnModels: ColumnModel[] = tableColumns.map((column) => {
      const isPrimaryKey = primaryColumns.has(column.column_name);
      const isAutoIncrement =
        column.is_identity === 'YES' ||
        (column.column_default !== null && column.column_default.startsWith('nextval('));
      const isForeignKey = foreignKeyColumns.has(column.column_name);
      const isEnum =
        column.is_pg_enum ||
        checkConstraints.some((check) => isEnumCheck(check.definition, column.column_name));
      return {
        name: column.column_name,
        kind: columnKind({
          base: baseKind(column.data_type, column.udt_name, column.is_pg_enum),
          isEnum,
          isPrimaryKey,
          isAutoIncrement,
          isForeignKey,
        }),
        dbType: dbType(column),
        nullable: column.is_nullable === 'YES',
        defaultText: renderDefault(column.column_default, column.is_identity === 'YES'),
        references: referenceFor(column.column_name, foreignKeyConstraints),
      };
    });

    const indexModels: IndexModel[] = indexes
      .filter((row) => row.table_name === tableName)
      .sort((left, right) => {
        const byColumns = compareText(left.columns.join(','), right.columns.join(','));
        return byColumns === 0 ? compareText(left.definition, right.definition) : byColumns;
      })
      .map((row) => ({
        name: row.name,
        columns: row.columns,
        unique: row.is_unique,
        where: row.where,
        definition: row.definition,
      }));

    const primaryKey = tableConstraints.find((row) => row.type === 'p')?.columns ?? [];
    const foreignKeys: ForeignKeyModel[] = [];
    for (const constraint of foreignKeyConstraints) {
      const unique = columnsAreUnique(tableName, constraint.columns, constraints, indexes);
      const identifying = constraint.columns.every((column) => primaryKey.includes(column));
      constraint.columns.forEach((column, index) => {
        const refTable = constraint.ref_table;
        const refColumn = constraint.ref_columns[index];
        if (refTable === null || refColumn === undefined) return;
        foreignKeys.push({
          table: tableName,
          constraint: constraint.name,
          column,
          refTable,
          refColumn,
          nullable: columnModels.find((model) => model.name === column)?.nullable ?? false,
          unique,
          identifying,
        });
      });
    }
    foreignKeys.sort(
      (left, right) =>
        compareText(left.column, right.column) ||
        compareText(left.refTable, right.refTable) ||
        compareText(left.refColumn, right.refColumn),
    );

    return { name: tableName, columns: columnModels, indexes: indexModels, foreignKeys };
  });

  return { tables };
}

/**
 * Reads the public schema through three parameterless catalog queries and builds a model.
 * @param sql - SQL client connected to the database to describe.
 * @returns Sorted schema model of the `public` schema.
 */
export async function readSchema(sql: SqlClient): Promise<SchemaModel> {
  const columnRows = await sql.query<RawColumnRow>(COLUMNS_SQL);
  const constraintRows = await sql.query<RawConstraintRow>(CONSTRAINTS_SQL);
  const indexRows = await sql.query<RawIndexRow>(INDEXES_SQL);
  return buildSchemaModel(
    columnRows.map(normalizeColumn),
    constraintRows.map(normalizeConstraint),
    indexRows.map(normalizeIndex),
  );
}

/**
 * Maps each `CREATE TABLE` name under `src` to the sorted repo-relative files that declare it.
 *
 * Directories named `__tests__` are skipped. Only `.ts` files are read. Files are visited in
 * sorted path order.
 * @param repoRoot - Repository root.
 * @returns Table name to sorted repo-relative source files.
 */
export async function sourceFiles(repoRoot: string): Promise<Map<string, string[]>> {
  const files = (await collectTypeScriptFiles(path.join(repoRoot, 'src'))).sort(compareText);
  const found = new Map<string, string[]>();
  for (const file of files) {
    const relative = path.relative(repoRoot, file).split(path.sep).join('/');
    const text = await readFile(file, 'utf8');
    for (const table of createTableNames(text)) {
      const list = found.get(table);
      if (list) list.push(relative);
      else found.set(table, [relative]);
    }
  }
  const result = new Map<string, string[]>();
  for (const table of [...found.keys()].sort(compareText)) {
    result.set(table, [...new Set(found.get(table) ?? [])].sort(compareText));
  }
  return result;
}

/** Repo-relative directory holding the per-store DDL reference files. */
export const SCHEMA_DIR = 'docs/schema';

/**
 * Reads every `docs/schema/*.sql` file: repo-relative POSIX path -> text, in sorted path order.
 * @param repoRoot - Absolute repository root.
 * @returns Sorted repo-relative POSIX paths to SQL text.
 */
export async function readSchemaFiles(repoRoot: string): Promise<Map<string, string>> {
  const directory = path.join(repoRoot, ...SCHEMA_DIR.split('/'));
  const names = await readdir(directory);
  const files = names
    .filter((name) => name.endsWith('.sql'))
    .map((name) => `${SCHEMA_DIR}/${name}`)
    .sort(compareText);
  const result = new Map<string, string>();
  for (const file of files) {
    result.set(file, await readFile(path.join(repoRoot, ...file.split('/')), 'utf8'));
  }
  return result;
}

/**
 * Maps each table that no `src` file creates to the schema file defining it.
 *
 * `schemaFiles` is path to SQL text (as from {@link readSchemaFiles}); `sources` is table to the
 * `src` paths that create it (as from {@link sourceFiles}). SQL `--` line comments are stripped
 * before the `CREATE TABLE [IF NOT EXISTS] <name>` scan. If several schema files define the same
 * external table, the first in sorted path order wins.
 * @param schemaFiles - Repo-relative schema path to SQL text.
 * @param sources - Table name to the src paths that create it.
 * @returns External table name to the winning schema file, in sorted table order.
 */
export function externalSchemaTables(
  schemaFiles: ReadonlyMap<string, string>,
  sources: ReadonlyMap<string, readonly string[]>,
): Map<string, string> {
  const found = new Map<string, string>();
  for (const file of [...schemaFiles.keys()].sort(compareText)) {
    const stripped = (schemaFiles.get(file) ?? '').replace(/--.*$/gm, '');
    for (const table of createTableNames(stripped)) {
      if (sources.has(table) || found.has(table)) continue;
      found.set(table, file);
    }
  }
  const result = new Map<string, string>();
  for (const table of [...found.keys()].sort(compareText)) {
    const file = found.get(table);
    if (file !== undefined) result.set(table, file);
  }
  return result;
}

/**
 * Lists the schema files that define at least one external table.
 *
 * A file that creates two tables, one of them external, is included. Paths are sorted and appear
 * once. A file whose only external table is also defined by an earlier file is still included.
 * @param schemaFiles - Repo-relative schema path to SQL text.
 * @param sources - Table name to the src paths that create it.
 * @returns Sorted schema paths that define at least one table missing from `sources`.
 */
export function externalSchemaFiles(
  schemaFiles: ReadonlyMap<string, string>,
  sources: ReadonlyMap<string, readonly string[]>,
): string[] {
  const files: string[] = [];
  for (const file of [...schemaFiles.keys()].sort(compareText)) {
    const stripped = (schemaFiles.get(file) ?? '').replace(/--.*$/gm, '');
    if (createTableNames(stripped).some((table) => !sources.has(table))) files.push(file);
  }
  return files;
}

/**
 * Renders the schema README and one markdown page per table.
 *
 * Keys are `docs/database/README.md` and `docs/database/tables/<table>.md`. Each page starts
 * with {@link GENERATED_HEADER} and is formatted as Markdown with the repo Prettier config.
 * @param model - Schema model to render.
 * @param sources - Table name to its source files.
 * @param repoRoot - Repository root, used to resolve the Prettier config.
 * @param external - Tables created outside this service, mapped to their `docs/schema` file.
 * @returns Path to Markdown text for the README and every table page.
 */
export async function renderPages(
  model: SchemaModel,
  sources: Map<string, string[]>,
  repoRoot: string,
  external: ReadonlyMap<string, string> = new Map(),
): Promise<Map<string, string>> {
  const resolved = await resolveConfig(path.join(repoRoot, '.prettierrc'));
  const options = { ...(resolved ?? {}), parser: 'markdown' as const };
  const effective = new Map(sources);
  for (const [table, file] of external) effective.set(table, [file]);
  const pages = new Map<string, string>();
  pages.set('docs/database/README.md', await format(renderReadme(model, effective), options));
  const foreignKeys = model.tables.flatMap((table) => table.foreignKeys);
  for (const table of model.tables) {
    pages.set(
      `docs/database/tables/${table.name}.md`,
      await format(
        renderTablePage(
          table,
          effective.get(table.name) ?? [],
          foreignKeys,
          external.get(table.name),
        ),
        options,
      ),
    );
  }
  return pages;
}

const COLUMNS_SQL =
  "SELECT c.table_name, c.column_name, c.ordinal_position::int AS ordinal_position, c.data_type, c.udt_name, c.character_maximum_length::int AS character_maximum_length, c.numeric_precision::int AS numeric_precision, c.numeric_scale::int AS numeric_scale, c.is_nullable, c.column_default, c.is_identity, EXISTS (SELECT 1 FROM pg_type ty JOIN pg_namespace ns ON ns.oid = ty.typnamespace WHERE ns.nspname = c.udt_schema AND ty.typname = c.udt_name AND ty.typtype = 'e') AS is_pg_enum FROM information_schema.columns c JOIN information_schema.tables t ON t.table_schema = c.table_schema AND t.table_name = c.table_name AND t.table_type = 'BASE TABLE' WHERE c.table_schema = 'public' ORDER BY c.table_name, c.ordinal_position";

const CONSTRAINTS_SQL =
  "SELECT cl.relname::text AS table_name, co.conname::text AS name, co.contype::text AS type, COALESCE((SELECT string_agg(a.attname::text, ',' ORDER BY k.ord) FROM unnest(co.conkey) WITH ORDINALITY AS k(attnum, ord) JOIN pg_attribute a ON a.attrelid = co.conrelid AND a.attnum = k.attnum), '') AS columns, pg_get_constraintdef(co.oid) AS definition, rcl.relname::text AS ref_table, COALESCE((SELECT string_agg(a.attname::text, ',' ORDER BY k.ord) FROM unnest(co.confkey) WITH ORDINALITY AS k(attnum, ord) JOIN pg_attribute a ON a.attrelid = co.confrelid AND a.attnum = k.attnum), '') AS ref_columns FROM pg_constraint co JOIN pg_class cl ON cl.oid = co.conrelid JOIN pg_namespace n ON n.oid = cl.relnamespace LEFT JOIN pg_class rcl ON rcl.oid = co.confrelid WHERE n.nspname = 'public' AND co.contype IN ('p', 'f', 'u', 'c') ORDER BY cl.relname, co.conname";

const INDEXES_SQL =
  "SELECT t.relname::text AS table_name, i.relname::text AS name, ix.indisunique AS is_unique, ix.indisprimary AS is_primary, pg_get_expr(ix.indpred, ix.indrelid) AS \"where\", pg_get_indexdef(ix.indexrelid) AS definition, (SELECT string_agg(COALESCE(a.attname::text, '(expression)'), ',' ORDER BY k.ord) FROM unnest(ix.indkey::int2[]) WITH ORDINALITY AS k(attnum, ord) LEFT JOIN pg_attribute a ON a.attrelid = ix.indrelid AND a.attnum = k.attnum AND k.attnum > 0 WHERE k.ord <= ix.indnkeyatts) AS columns FROM pg_index ix JOIN pg_class t ON t.oid = ix.indrelid JOIN pg_class i ON i.oid = ix.indexrelid JOIN pg_namespace n ON n.oid = t.relnamespace WHERE n.nspname = 'public' AND t.relkind = 'r' ORDER BY t.relname, i.relname";

const CREATE_TABLE_PATTERN =
  /create\s+table\s+(?:if\s+not\s+exists\s+)?(?:public\.)?"?([A-Za-z_][A-Za-z0-9_]*)\b"?/gi;

type RawColumnRow = {
  table_name: string;
  column_name: string;
  ordinal_position: number | string;
  data_type: string;
  udt_name: string;
  character_maximum_length: number | string | null;
  numeric_precision: number | string | null;
  numeric_scale: number | string | null;
  is_nullable: string;
  column_default: string | null;
  is_identity: string;
  is_pg_enum: unknown;
};

type RawConstraintRow = {
  table_name: string;
  name: string;
  type: string;
  columns: string | null;
  definition: string;
  ref_table: string | null;
  ref_columns: string | null;
};

type RawIndexRow = {
  table_name: string;
  name: string;
  is_unique: unknown;
  is_primary: unknown;
  where: string | null;
  definition: string;
  columns: string | null;
};

function compareText(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

function numberOrNull(value: number | string | null): number | null {
  if (value === null) return null;
  return Number(value);
}

function splitColumns(value: string | null): string[] {
  if (value === null || value === '') return [];
  return value.split(',');
}

function yesNo(value: string): 'YES' | 'NO' {
  if (value === 'YES' || value === 'NO') return value;
  throw new Error(`Expected YES or NO, received ${value}`);
}

function constraintType(value: string): ConstraintRow['type'] {
  if (value === 'p' || value === 'f' || value === 'u' || value === 'c') return value;
  throw new Error(`Expected constraint type, received ${value}`);
}

function asBoolean(value: unknown): boolean {
  if (value === true || value === false) return value;
  if (value === 't' || value === 'true' || value === '1' || value === 1) return true;
  if (value === 'f' || value === 'false' || value === '0' || value === 0 || value === null) {
    return false;
  }
  throw new Error('Expected a boolean catalog value');
}

function normalizeColumn(row: RawColumnRow): ColumnRow {
  return {
    table_name: row.table_name,
    column_name: row.column_name,
    ordinal_position: Number(row.ordinal_position),
    data_type: row.data_type,
    udt_name: row.udt_name,
    character_maximum_length: numberOrNull(row.character_maximum_length),
    numeric_precision: numberOrNull(row.numeric_precision),
    numeric_scale: numberOrNull(row.numeric_scale),
    is_nullable: yesNo(row.is_nullable),
    column_default: row.column_default,
    is_identity: yesNo(row.is_identity),
    is_pg_enum: asBoolean(row.is_pg_enum),
  };
}

function normalizeConstraint(row: RawConstraintRow): ConstraintRow {
  return {
    table_name: row.table_name,
    name: row.name,
    type: constraintType(row.type),
    columns: splitColumns(row.columns),
    definition: row.definition,
    ref_table: row.ref_table,
    ref_columns: splitColumns(row.ref_columns),
  };
}

function normalizeIndex(row: RawIndexRow): IndexRow {
  return {
    table_name: row.table_name,
    name: row.name,
    columns: splitColumns(row.columns),
    is_unique: asBoolean(row.is_unique),
    is_primary: asBoolean(row.is_primary),
    where: row.where,
    definition: row.definition,
  };
}

function referenceFor(
  column: string,
  foreignKeys: readonly ConstraintRow[],
): { table: string; column: string } | null {
  for (const constraint of foreignKeys) {
    const index = constraint.columns.indexOf(column);
    if (index < 0) continue;
    const table = constraint.ref_table;
    const refColumn = constraint.ref_columns[index];
    if (table !== null && refColumn !== undefined) return { table, column: refColumn };
  }
  return null;
}

/**
 * Whether a primary key, unique constraint, or qualifying unique index has exactly this column set.
 * Membership is compared without regard to order. A wider unique that merely covers the set does not
 * count. A partial index qualifies only for a single column when its predicate is exactly that column
 * `IS NOT NULL`.
 * @param table - Table that owns the columns.
 * @param columns - Column set that must match exactly.
 * @param constraints - Catalog constraints, including primary keys and unique constraints.
 * @param indexes - Catalog indexes, including unique indexes.
 * @returns True when some primary-key or unique constraint, or a qualifying unique index, has exactly
 * this column set.
 */
function columnsAreUnique(
  table: string,
  columns: readonly string[],
  constraints: readonly ConstraintRow[],
  indexes: readonly IndexRow[],
): boolean {
  /**
   * Whether two column lists contain the same members the same number of times.
   * @param candidate - Column list to compare with `columns`.
   * @returns True when the lists are the same multiset.
   */
  const sameSet = (candidate: readonly string[]): boolean => {
    if (candidate.length !== columns.length) return false;
    const remaining = new Map<string, number>();
    for (const name of columns) remaining.set(name, (remaining.get(name) ?? 0) + 1);
    for (const name of candidate) {
      const count = remaining.get(name);
      if (count === undefined || count === 0) return false;
      remaining.set(name, count - 1);
    }
    return true;
  };
  const constraintUnique = constraints.some(
    (row) =>
      row.table_name === table && (row.type === 'u' || row.type === 'p') && sameSet(row.columns),
  );
  const singleColumn = columns.length === 1 ? columns[0] : undefined;
  const indexUnique = indexes.some(
    (row) =>
      row.table_name === table &&
      row.is_unique &&
      sameSet(row.columns) &&
      (row.where === null ||
        (singleColumn !== undefined && matchesNotNullPredicate(row.where, singleColumn))),
  );
  return constraintUnique || indexUnique;
}

function matchesNotNullPredicate(predicate: string, column: string): boolean {
  const clause = stripOuterParens(predicate);
  return new RegExp(`^${columnRef(column)}\\s+IS\\s+NOT\\s+NULL$`, 'i').test(clause);
}

async function collectTypeScriptFiles(directory: string): Promise<string[]> {
  const entries = await readdir(directory, { withFileTypes: true });
  const files: string[] = [];
  for (const entry of entries) {
    if (entry.isDirectory() && entry.name === '__tests__') continue;
    const fullPath = path.join(directory, entry.name);
    if (entry.isDirectory()) files.push(...(await collectTypeScriptFiles(fullPath)));
    else if (entry.isFile() && entry.name.endsWith('.ts')) files.push(fullPath);
  }
  return files;
}

function createTableNames(source: string): string[] {
  const names: string[] = [];
  for (const match of source.matchAll(CREATE_TABLE_PATTERN)) {
    const name = match[1];
    if (name !== undefined) names.push(name);
  }
  return names;
}

function renderReadme(model: SchemaModel, sources: Map<string, string[]>): string {
  const columnCount = model.tables.reduce((total, table) => total + table.columns.length, 0);
  const foreignKeyCount = model.tables.reduce(
    (total, table) => total + constraintCount(table.foreignKeys),
    0,
  );
  const rows = model.tables.map((table) => {
    const paths = sources.get(table.name) ?? [];
    return `| ${markdownCell(`[${codeSpan(table.name)}](tables/${table.name}.md)`)} | ${markdownCell(sourceLinks(paths, '../../'))} | ${table.columns.length} | ${constraintCount(table.foreignKeys)} |`;
  });
  return [
    GENERATED_HEADER,
    '',
    '# Database schema',
    '',
    'The pages are generated from the schema the server creates at boot. `ENUM` means a fixed set of values: a CHECK constraint that pins the column to a literal list, or a Postgres enum type; the stored type is shown under Database type. Regenerate with `DATABASE_URL=postgres://… bun run db:docs`. Tables created outside this service are built from their `docs/schema/*.sql` definition.',
    '',
    `- Tables: ${model.tables.length}`,
    `- Columns: ${columnCount}`,
    `- Foreign keys: ${foreignKeyCount}`,
    '',
    '| Table | Source | Columns | Foreign keys |',
    '| --- | --- | --- | --- |',
    ...rows,
    '',
  ].join('\n');
}

function renderTablePage(
  table: TableModel,
  paths: readonly string[],
  foreignKeys: readonly ForeignKeyModel[],
  externalFile: string | undefined,
): string {
  const sourceLine =
    externalFile === undefined
      ? `Source: ${sourceLinks(paths, '../../../')}`
      : `Source: ${sourceLinks(paths, '../../../')} Created outside this service; definition from ${externalFile}.`;
  const parts = [
    GENERATED_HEADER,
    '',
    `# ${codeSpan(table.name)}`,
    '',
    sourceLine,
    '',
    '## Columns',
    '',
    renderColumns(table),
    '',
    '## Indexes',
    '',
    renderIndexes(table),
    '',
    '## Referenced by',
    '',
    renderReferencedBy(table.name, foreignKeys),
  ];
  const relations = renderRelations(table.name, foreignKeys);
  if (relations !== null) parts.push('', '## Relations', '', relations);
  parts.push('');
  return parts.join('\n');
}

function renderColumns(table: TableModel): string {
  const rows = table.columns.map((column) => {
    const reference =
      column.references === null
        ? '–'
        : `[${codeSpan(column.references.table)}.${codeSpan(column.references.column)}](${column.references.table}.md)`;
    return `| ${markdownCell(codeSpan(column.name))} | ${markdownCell(column.kind)} | ${markdownCell(codeSpan(column.dbType))} | ${column.nullable ? 'Yes' : 'No'} | ${markdownCell(column.defaultText)} | ${markdownCell(reference)} |`;
  });
  return [
    '| Column | Kind | Database type | Nullable | Default | References |',
    '| --- | --- | --- | --- | --- | --- |',
    ...rows,
  ].join('\n');
}

function renderIndexes(table: TableModel): string {
  if (table.indexes.length === 0) return 'None.';
  const rows = table.indexes.map((index) => {
    const columns = index.columns.map((column) => codeSpan(column)).join(', ');
    return `| ${markdownCell(columns)} | ${index.unique ? 'Yes' : 'No'} | ${markdownCell(codeOrDash(index.where))} | ${markdownCell(codeSpan(index.definition))} |`;
  });
  return ['| Columns | Unique | Where | Definition |', '| --- | --- | --- | --- |', ...rows].join(
    '\n',
  );
}

function renderReferencedBy(tableName: string, foreignKeys: readonly ForeignKeyModel[]): string {
  const incoming = foreignKeys
    .filter((foreignKey) => foreignKey.refTable === tableName)
    .sort(
      (left, right) =>
        compareText(left.table, right.table) ||
        compareText(left.column, right.column) ||
        compareText(left.refColumn, right.refColumn),
    );
  if (incoming.length === 0) return 'None.';
  const rows = incoming.map(
    (foreignKey) =>
      `| ${markdownCell(codeSpan(foreignKey.table))} | ${markdownCell(codeSpan(foreignKey.column))} | ${markdownCell(codeSpan(foreignKey.refColumn))} |`,
  );
  return ['| Table | Column | Points to |', '| --- | --- | --- |', ...rows].join('\n');
}

/**
 * Mermaid relationships of one table, one edge per foreign-key constraint.
 * A composite key is one edge labelled with all its columns; it is optional when any of them
 * accepts NULL, because such a row is not checked against the referenced table.
 * @param tableName - Table whose page is rendered.
 * @param foreignKeys - Column-level foreign keys of every table.
 * @returns Mermaid block, or null when the table has no relationship.
 */
/**
 * Number of foreign-key constraints, counting a composite key once.
 * @param foreignKeys - Column-level foreign keys of one table.
 * @returns Distinct constraints.
 */
function constraintCount(foreignKeys: readonly ForeignKeyModel[]): number {
  return new Set(foreignKeys.map((foreignKey) => foreignKey.constraint)).size;
}

function renderRelations(
  tableName: string,
  foreignKeys: readonly ForeignKeyModel[],
): string | null {
  const edges = new Map<string, { key: ForeignKeyModel; columns: string[]; nullable: boolean }>();
  for (const foreignKey of foreignKeys) {
    if (foreignKey.table !== tableName && foreignKey.refTable !== tableName) continue;
    const id = `${foreignKey.table}\u0000${foreignKey.constraint}`;
    const edge = edges.get(id);
    if (edge === undefined) {
      edges.set(id, {
        key: foreignKey,
        columns: [foreignKey.column],
        nullable: foreignKey.nullable,
      });
      continue;
    }
    edge.columns.push(foreignKey.column);
    edge.nullable ||= foreignKey.nullable;
  }
  const lines = [
    ...new Set(
      [...edges.values()].map(
        ({ key, columns, nullable }) =>
          `    "${escapeMermaid(key.table)}" ${cardinality(nullable, key.unique, key.identifying)} "${escapeMermaid(key.refTable)}" : "${escapeMermaid(columns.join(', '))}"`,
      ),
    ),
  ].sort(compareText);
  if (lines.length === 0) return null;
  return ['```mermaid', 'erDiagram', ...lines, '```'].join('\n');
}

function sourceLinks(paths: readonly string[], prefix: string): string {
  if (paths.length === 0) return '–';
  return paths.map((file) => `[${file}](${prefix}${file})`).join(', ');
}

function codeOrDash(value: string | null): string {
  if (value === null || value === '–') return '–';
  return codeSpan(value);
}

function codeSpan(value: string): string {
  return `\`${value.replace(/`/g, "'")}\``;
}

function markdownCell(value: string): string {
  return value.replace(/\|/g, '\\|').replace(/\r?\n/g, ' ');
}

function escapeMermaid(value: string): string {
  return value.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
}

/**
 * Repository root used when reading sources and writing `docs/database`.
 * One directory above this module (`integration/`).
 */
export const REPO_ROOT: string = path.resolve(import.meta.dir, '..');

/**
 * Returns true when `error` is a Node `ENOENT` failure.
 * @param error - Unknown rejection or thrown value.
 * @returns Whether the error code is `ENOENT`.
 */
function isEnoent(error: unknown): boolean {
  return (
    typeof error === 'object' &&
    error !== null &&
    'code' in error &&
    (error as { code: unknown }).code === 'ENOENT'
  );
}

/**
 * Loads the committed database docs into a path → markdown map.
 * Missing `README.md` or a missing `tables` directory yields an empty contribution, not an error.
 * @param repoRoot - Absolute repository root.
 * @returns Repo-relative POSIX paths (`docs/database/...`) to file text.
 */
export async function readCommitted(repoRoot: string): Promise<Map<string, string>> {
  const committed = new Map<string, string>();
  const readmeRel = 'docs/database/README.md';
  try {
    const text = await readFile(path.join(repoRoot, 'docs', 'database', 'README.md'), 'utf8');
    committed.set(readmeRel, text);
  } catch (error) {
    if (!isEnoent(error)) throw error;
  }

  const tablesDir = path.join(repoRoot, 'docs', 'database', 'tables');
  let names: string[];
  try {
    names = await readdir(tablesDir);
  } catch (error) {
    if (!isEnoent(error)) throw error;
    return committed;
  }

  for (const name of names) {
    if (!name.endsWith('.md')) continue;
    const rel = `docs/database/tables/${name}`;
    const text = await readFile(path.join(tablesDir, name), 'utf8');
    committed.set(rel, text);
  }
  return committed;
}

/**
 * Creates a temporary Postgres database from template0, runs `run` against its URL, then drops it.
 * A failure while creating the database or building the URL is rethrown after the admin client is
 * closed, and the database is dropped when it was created.
 * A drop failure after `run` already threw is logged and the original error is rethrown.
 * A drop failure after a successful `run` is thrown after cleanup.
 * @param adminUrl - Admin connection string allowed to `CREATE DATABASE`.
 * @param run - Callback receiving the scratch database URL.
 * @returns Whatever `run` returns.
 * @throws The error of `run`, create, or URL setup, or the drop error when nothing else failed.
 */
export async function withScratchDatabase<T>(
  adminUrl: string,
  run: (url: string) => Promise<T>,
): Promise<T> {
  const admin = new SQL(adminUrl);
  const name = `gifts_schema_${randomBytes(6).toString('hex')}`;

  let runError: unknown;
  let runFailed = false;
  let result: T | undefined;
  let dropError: unknown;
  let dropFailed = false;
  let created = false;
  try {
    await admin.unsafe(`CREATE DATABASE "${name}" TEMPLATE template0`);
    created = true;
    const scratch = new URL(adminUrl);
    scratch.pathname = `/${name}`;
    const scratchUrl = scratch.toString();
    result = await run(scratchUrl);
  } catch (error) {
    runFailed = true;
    runError = error;
  } finally {
    if (created) {
      try {
        await admin.unsafe(`DROP DATABASE IF EXISTS "${name}" WITH (FORCE)`);
      } catch (error) {
        dropFailed = true;
        dropError = error;
        console.error(error);
      }
    }
    try {
      if (typeof admin.close === 'function') await admin.close();
    } catch (closeError) {
      console.error(closeError);
    }
  }
  if (runFailed) throw runError;
  if (dropFailed) throw dropError;
  return result as T;
}

/** Throwaway 64-hex KEK; the scratch database stores no secrets. */
const SCRATCH_NOSTR_KEK = '0'.repeat(64);

/** Throwaway 64-hex recovery share KEK, distinct from {@link SCRATCH_NOSTR_KEK}. */
const SCRATCH_RECOVERY_SHARE_KEK = '1'.repeat(64);

/**
 * Builds schema reference pages against a scratch database migrated by boot stores.
 * Network fetches and zap relays are disabled so generation stays offline.
 * @param adminUrl - Admin connection string used to create the scratch database.
 * @returns Rendered repo-relative path → markdown.
 */
export async function generate(adminUrl: string): Promise<Map<string, string>> {
  return withScratchDatabase(adminUrl, async (url: string): Promise<Map<string, string>> => {
    const sql = new SQL(url);
    const client: SqlClient = {
      async query<T>(text: string, params: readonly unknown[] = []): Promise<T[]> {
        return (await sql.unsafe(text, [...params])) as T[];
      },
      async execute(text: string, params: readonly unknown[] = []): Promise<void> {
        await sql.unsafe(text, [...params]);
      },
    };
    // Boot requires both KEKs (exactly 64 lowercase hex characters, parseKekHex)
    // whenever a database is set. The scratch database holds no secrets, so
    // fixed throwaway values are fine.
    const previousKek = process.env['NOSTR_NSEC_KEK'];
    if (previousKek === undefined || previousKek.trim() === '') {
      process.env['NOSTR_NSEC_KEK'] = SCRATCH_NOSTR_KEK;
    }
    const previousRecoveryKek = process.env['RECOVERY_SHARE_KEK'];
    if (previousRecoveryKek === undefined || previousRecoveryKek.trim() === '') {
      process.env['RECOVERY_SHARE_KEK'] = SCRATCH_RECOVERY_SHARE_KEK;
    }
    try {
      const sources = await sourceFiles(REPO_ROOT);
      const schemaFiles = await readSchemaFiles(REPO_ROOT);
      // Tables created outside this service are built from their docs/schema definition.
      for (const file of externalSchemaFiles(schemaFiles, sources)) {
        await sql.unsafe(schemaFiles.get(file) ?? '');
      }
      const external = externalSchemaTables(schemaFiles, sources);
      await openBootStores(url, () => client, {
        fetchImpl: async (): Promise<Response> => {
          throw new Error('offline');
        },
        now: () => 0,
        zapRelayUrls: [],
      });
      const model = await readSchema(client);
      return await renderPages(model, sources, REPO_ROOT, external);
    } finally {
      // openBootStores installs a process-wide sink that writes to this scratch database.
      setDiagnosticSink(null);
      if (previousKek === undefined) delete process.env['NOSTR_NSEC_KEK'];
      else process.env['NOSTR_NSEC_KEK'] = previousKek;
      if (previousRecoveryKek === undefined) delete process.env['RECOVERY_SHARE_KEK'];
      else process.env['RECOVERY_SHARE_KEK'] = previousRecoveryKek;
      if (typeof sql.close === 'function') await sql.close();
    }
  });
}

/**
 * Writes every rendered page under the repository and deletes stale table pages only.
 * @param rendered - Path → markdown produced by {@link generate}.
 * @param root - Directory the repo-relative paths resolve against.
 * @returns Counts of files written and stale table pages removed.
 */
export async function writeRendered(
  rendered: Map<string, string>,
  root: string = REPO_ROOT,
): Promise<{ written: number; removed: number }> {
  const tablesDir = path.join(root, 'docs', 'database', 'tables');
  await mkdir(tablesDir, { recursive: true });
  for (const [rel, body] of rendered) {
    const abs = path.join(root, ...rel.split('/'));
    await mkdir(path.dirname(abs), { recursive: true });
    await writeFile(abs, body);
  }

  let removed = 0;
  const existing = await readdir(tablesDir);
  for (const name of existing) {
    if (!name.endsWith('.md')) continue;
    const rel = `docs/database/tables/${name}`;
    if (!rendered.has(rel)) {
      await rm(path.join(tablesDir, name));
      removed += 1;
    }
  }
  return { written: rendered.size, removed };
}

/**
 * CLI entry for `bun integration/db-schema-reference.ts --write|--check`.
 * @param argv - Arguments after the script name.
 * @param env - Process environment; `DATABASE_URL` is required.
 * @returns Exit code: `0` success, `1` docs drift, `2` usage or missing URL.
 * @throws When generating the pages fails, for example because the database is unreachable.
 */
export async function runCli(
  argv: readonly string[],
  env: Readonly<Record<string, string | undefined>>,
): Promise<number> {
  const mode = argv[0];
  if (argv.length !== 1 || (mode !== '--write' && mode !== '--check')) {
    console.error('Usage: bun integration/db-schema-reference.ts --write|--check');
    return 2;
  }

  const databaseUrl = env['DATABASE_URL'];
  if (databaseUrl === undefined || databaseUrl.trim() === '') {
    console.error('DATABASE_URL is required');
    return 2;
  }

  const rendered = await generate(databaseUrl);
  if (mode === '--write') {
    const { written, removed } = await writeRendered(rendered);
    console.warn(`Wrote ${written} files, removed ${removed} stale`);
    return 0;
  }

  const committed = await readCommitted(REPO_ROOT);
  const diff = compareToCommitted(rendered, committed);
  if (diff.missing.length === 0 && diff.differing.length === 0 && diff.stale.length === 0) {
    console.warn('docs/database is up to date');
    return 0;
  }
  for (const rel of diff.missing) console.error(`missing: ${rel}`);
  for (const rel of diff.differing) console.error(`differs: ${rel}`);
  for (const rel of diff.stale) console.error(`stale: ${rel}`);
  console.error('Run: bun run db:docs');
  return 1;
}

if (import.meta.main) {
  try {
    const code = await runCli(process.argv.slice(2), process.env);
    process.exit(code);
  } catch (error) {
    console.error(error);
    process.exit(1);
  }
}
